parameters.jsCode:
const records = $input.all();

const tickets = [];

// Collect all unresolved tickets
for (const item of records) {
  const ticket = item.json.fields || item.json;

  if (
    ticket["Ticket ID"] &&
    ticket["Status"] !== "Resolved"
  ) {
    tickets.push(ticket);
  }
}

// Total unresolved tickets
const total = tickets.length;

// Count high-priority tickets
const high = tickets.filter(
  ticket => ticket["Priority"] === "High"
).length;

// Count tickets needing human review
const needsReview = tickets.filter(
  ticket => ticket["Status"] === "Needs Review"
).length;

// Count tickets awaiting approval
const awaitingApproval = tickets.filter(
  ticket => ticket["Status"] === "Awaiting Approval"
).length;

// Count tickets with responses sent but not resolved
const responseSent = tickets.filter(
  ticket => ticket["Status"] === "Response Sent"
).length;

// Count tickets stuck in Sending
const sending = tickets.filter(
  ticket => ticket["Status"] === "Sending"
).length;

// Group tickets by status
const statusCounts = {};

for (const ticket of tickets) {
  const status = ticket["Status"] || "Unknown";

  statusCounts[status] = (statusCounts[status] || 0) + 1;
}

// Prepare status breakdown
const statusBreakdown = Object.entries(statusCounts)
  .map(([status, count]) => `${status}: ${count}`)
  .join("\n") || "No unresolved tickets";

// Get high-priority ticket IDs
const highPriorityTickets = tickets
  .filter(ticket => ticket["Priority"] === "High")
  .slice(0, 5)
  .map(ticket => ticket["Ticket ID"])
  .join(", ") || "None";

// Get today's date in Nigeria
const date = new Date().toLocaleDateString("en-GB", {
  timeZone: "Africa/Lagos"
});

// Generate daily Telegram report
const report = `
📊 SUPPORTFLOW AI
DAILY UNRESOLVED TICKET REPORT

📅 Date: ${date}

📌 Total Unresolved Tickets: ${total}

🚨 High Priority: ${high}
👤 Needs Human Review: ${needsReview}
⏳ Awaiting Approval: ${awaitingApproval}
📩 Response Sent (Not Resolved): ${responseSent}
⚠️ Sending - Check Delivery: ${sending}

📋 BREAKDOWN BY STATUS
${statusBreakdown}

🔴 HIGH-PRIORITY TICKET IDs
${highPriorityTickets}

✅ REQUIRED ACTION

1. Review all unresolved tickets in Airtable.

2. Prioritize high-priority complaints.

3. Follow up on tickets marked Response Sent.

4. Attend to tickets requiring human review.

5. Investigate tickets stuck in Sending before retrying.

6. Mark complaints as Resolved only after confirming the issue has been addressed.

SupportFlow AI - Automated Daily Report
Educational demonstration only.
`;

// Return report to Telegram
return [
  {
    json: {
      report: report,
      totalUnresolved: total,
      highPriority: high,
      needsReview: needsReview,
      awaitingApproval: awaitingApproval,
      responseSent: responseSent,
      sending: sending
    }
  }
];
